/// A `wp_theme_json_get_style_nodes` callback that reverses the list.
struct Reverse;

impl ThemeJsonFilters for Reverse {
    fn style_nodes(&self, nodes: Value) -> Result<Value, ThemeJsonError> {
        let Value::Array(items) = nodes else {
            return Ok(nodes);
        };
        Ok(php_list(items.into_iter().rev().map(|(_, v)| v).collect()))
    }
}

